package com.mfg.srm.entity;import jakarta.persistence.*;import lombok.*;import java.math.*;import java.time.*;
@Entity @Table(name="srm_delivery",catalog="src_srm") @Getter @Setter @NoArgsConstructor public class SupplierDelivery{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="delivery_no")private String deliveryNo;@Column(name="purchase_order_no")private String purchaseOrderNo;@Column(name="supplier_code")private String supplierCode;@Column(name="material_code")private String materialCode;@Column(name="delivery_qty")private BigDecimal deliveryQty;@Column(name="qualified_qty")private BigDecimal qualifiedQty=BigDecimal.ZERO;@Column(name="rejected_qty")private BigDecimal rejectedQty=BigDecimal.ZERO;@Column(name="expected_date")private LocalDate expectedDate;@Column(name="actual_date")private LocalDate actualDate;@Column(name="delay_days")private Integer delayDays=0;@Column(name="batch_no")private String batchNo;@Column(name="inspection_status")private String inspectionStatus="PENDING";@Column(name="is_stocked")private Boolean stocked=false;@Column(name="created_by")private String createdBy;@Column(name="asn_no")private String asnNo;@Column(name="receipt_no")private String receiptNo;@Column(name="created_at",insertable=false,updatable=false)private LocalDateTime createdAt;@Column(name="updated_at",insertable=false,updatable=false)private LocalDateTime updatedAt;}
